package com.slcm.portal;
import com.slcm.portal.auth.*; import com.slcm.portal.user.*; import org.junit.jupiter.api.Test; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.http.MediaType; import org.springframework.security.test.context.support.WithMockUser; import org.springframework.test.web.servlet.MockMvc; import org.springframework.beans.factory.annotation.Autowired; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(controllers=AuthController.class) class AuthControllerWebTest {
 @Autowired MockMvc mvc; @MockBean AuthService auth; @MockBean UserRepository users; @MockBean JwtAuthenticationFilter jwtFilter;
 @Test void loginSuccess() throws Exception {when(auth.login(any())).thenReturn(new AuthResponse("jwt","student.demo",UserRole.STUDENT));mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"student.demo\",\"password\":\"password\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.token").value("jwt"));}
 @Test void loginValidationFailure() throws Exception {mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"\",\"password\":\"\"}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.status").value(400));verifyNoInteractions(auth);}
 @Test void loginCredentialFailure() throws Exception {when(auth.login(any())).thenThrow(new org.springframework.security.authentication.BadCredentialsException("bad"));mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"student.demo\",\"password\":\"wrong\"}")).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.message").value("Invalid username or password"));}
 @Test @WithMockUser(username="student.demo") void meReturnsIdentity() throws Exception {User u=mock(User.class);when(u.getId()).thenReturn(1L);when(u.getUsername()).thenReturn("student.demo");when(u.getRole()).thenReturn(UserRole.STUDENT);when(u.isEnabled()).thenReturn(true);when(users.findByUsername("student.demo")).thenReturn(java.util.Optional.of(u));mvc.perform(get("/api/auth/me")).andExpect(status().isOk()).andExpect(jsonPath("$.username").value("student.demo"));}
 @Test void meRejectsAnonymous() throws Exception {mvc.perform(get("/api/auth/me")).andExpect(status().isUnauthorized());}
}
